[asy]
draw((-5,-5)--(10,3)--(0,10)--cycle);
draw((-2.5,2.5)--(2.5,-1));
label("$A$",(-5,-5),SW);
label("$B$",(0,10),N);
label("$C$",(10,3),SE);
label("$D$",(-2.5,2.5),NW);
label("$E$",(2.5,-1),SE);
[/asy]

